    ctx = {"worktree": "/wt"}
    cmd = camera_command({}, ctx)
    argv = shlex.split(cmd)
    assert argv[0] == "ffmpeg" and "-frames:v" in argv
    assert argv[-1] == "/wt/scratch/camera/last-frame.jpg"
    for bad in ("../escape.jpg", "/etc/x.jpg", "has space.jpg"):
        try:
            camera_command({"out_path": bad}, ctx); assert False
